mapper.select:
/* selectRoleList */ select tcr.role_id ,tcr.sort_sn ,tcr.role_nm ,tcr.usg_yn ,tcr.del_yn ,tcr.crt_user_id ,tcr.crt_date ,tcr.upt_user_id ,(select tu.user_nm from SYS_USER tu where tu.user_id = tcr.upt_user_id) as user_nm ,fn_get_time(tcr.upt_date, #{tzon_cd},'DA', '-') as upt_date ,fn_get_time(tcr.upt_date, #{tzon_cd},'TS', ':') as upt_tm ,(select count(1) from SYS_USER_ROLE tur where tur.role_id = tcr.role_id) as usr_cnt ,(select distinct tcm.mlang_cd from sys_mlang tcm where tcm.mlang_cd = tcr.role_id and tcm.mlang_tp_cd = 'RL' and tcm.lang_cd = #{sess_lang_cd} and tcm.del_yn = 'N') as mlang_id from SYS_ROLE tcr where tcr.del_yn = 'N'
and tcr.role_nm like concat('%', trim(#{role_nm}), '%')
and tcr.usg_yn = #{usg_yn}
order by tcr.sort_sn asc

mapper.update:
/* updateRoleList */
update SYS_ROLE set
	 sort_sn = CAST (#{sort_sn} AS BIGINT)
	,role_nm = #{role_nm}
	,usg_yn = #{usg_yn}
	,upt_user_id = #{sess_user_id}
	,upt_date = CURRENT_TIMESTAMP
where role_id = #{role_id}

/* deleteRoleList */
update SYS_ROLE set
	 del_yn = 'Y'
	,usg_yn = 'N'
	,upt_user_id = #{sess_user_id}
	,upt_date = CURRENT_TIMESTAMP
where role_id = #{role_id}

mapper.select:
/* selectUserRoleList */ select tur.user_id ,tur.role_id ,tcr.role_nm ,tu.user_nm ,case when tur.usg_yn = 'Y' and tcr.usg_yn = 'Y' and tu.usg_yn = 'Y' then 'Y' else 'N' end as usg_yn ,tur.crt_user_id ,tur.crt_date ,tur.upt_user_id ,tur.upt_date ,'N' as row_status from SYS_USER_ROLE tur left outer join SYS_ROLE tcr on tur.role_id = tcr.role_id left outer join SYS_USER tu on tur.user_id = tu.user_id where tur.del_yn = 'N' and tcr.del_yn = 'N' and tu.del_yn = 'N'
and tur.user_id = #{usr_id}
and tu.user_nm like concat('%', trim(#{user_nm}), '%')
and tcr.role_nm like concat('%', trim(#{role_nm}), '%')
order by tcr.sort_sn asc, tur.user_id asc

mapper.update:
		merge 
		 into SYS_USER_ROLE as tur
		using (select 1 as dual) as b
		   on (		tur.user_id 	= #{sess_user_id} 
		   		and tur.role_id = #{role_id} )
		 when matched then     
   update set usg_yn 		= #{usg_yn}
     		 ,del_yn 		= #{del_yn} 
			 ,upt_user_id 	= #{sess_user_id}
			 ,upt_date 		= CURRENT_TIMESTAMP
		 when not matched then	    
       insert (
        	  user_id 
        	 ,role_id 
        	 ,usg_yn 
        	 ,del_yn 
        	 ,crt_user_id 
        	 ,crt_date
        	 ,upt_user_id 
        	 ,upt_date
			  ) 
	   values (
			  #{sess_user_id}
			 ,#{role_id}
			 ,#{usg_yn}
			 ,#{del_yn}
			 ,#{sess_user_id}
			 ,CURRENT_TIMESTAMP
			 ,#{sess_user_id}
			 ,CURRENT_TIMESTAMP
		      );

mapper.insert:
/* insertUserRole */
insert into SYS_USER_ROLE (
	   user_id
	  ,role_id
	  ,usg_yn
	  ,del_yn
	  ,crt_date
	  ,upt_date
	  ,crt_user_id
	  ,upt_user_id
) values (
	   #{sess_user_id}
	  ,#{role_id}
	  ,'Y'
	  ,'N'
	  ,CURRENT_TIMESTAMP
	  ,CURRENT_TIMESTAMP
	  ,#{sess_user_id}
	  ,#{sess_user_id}
)
